import { defineExperiment } from "niceeval";
import { gptResearcher } from "../agents/gpt-researcher.ts";

export default defineExperiment({
  description: "GPT Researcher local-document baseline",
  agent: gptResearcher({
    wsUrl: process.env.GPTR_WS_URL ?? "ws://localhost:8000/ws",
    request: {
      reportSource: "local",
      reportType: "research_report",
      tone: "Objective",
    },
  }),
  attempts: 1,
  maxConcurrency: 1,
});

